head.script:
// 원본 : ULDINF20000 표준코드 조회 (/ui/inf/srch/ULDINF20000.xml)

/*
 * 화면 동작
 * 1. 화면 로딩시 최근 1개월을 조회기간 기본값으로 설정
 * 2. 「검색구분」 선택에 따라 「종목명·코드」 또는 「상장일자」 입력 행을 전환
 * 3. 기간 버튼(1개월·3개월·6개월·1년) 클릭시 조회기간을 설정
 * 4. 「조회」 클릭 또는 조회영역에서 엔터 입력시 목록을 페이징 조회
 * 5. 「엑셀」 은 현재 페이지분, 「전체 엑셀」 은 조건에 맞는 전체를 다운로드
 * 6. 「초기화」 클릭시 조회조건과 목록을 함께 비움
 *
 * 담긴 패턴
 * - 검색구분에 따라 조회 항목 전환 (행 show/hide)
 * - 기간 버튼 (1개월·3개월·6개월·1년) 과 시작일>종료일 검증
 * - 조회조건 필수 검증 ($c.validate.validateDataCollect)
 * - 조회영역 엔터키로 조회 ($c.win.setEnterKeyEvent)
 * - 목록 페이징 ($c.sbm.setPagingInfo)
 * - 엑셀 다운로드 현재 페이지분 / 조건에 맞는 전체 ($c.data.downloadGridViewExcel)
 *
 * 복사해서 쓰는 순서
 * 1. 파일명과 meta_screenId 를 실제 화면ID 로 변경
 * 2. dma_search 키와 조회조건 마크업을 업무 항목으로 교체
 * 3. dlt_main 컬럼과 gridView 컬럼을 업무 항목으로 교체 (gBody 의 column id 는 dataList 와 일치 필수)
 * 4. 각 통신의 action 경로를 실 API 로 교체
 * 5. searchList() 의 검증 fields 를 업무 규칙으로 교체
 * 6. 필요 없는 기능(검색구분 전환·기간·엑셀)은 함수와 마크업을 함께 삭제
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "ULDINF20000";

// 화면 상태값
scwin.pageIndex = 1;		// 현재 페이지
scwin.pageItemCnt = 10;		// 페이지당 건수. 그리드의 visibleRowNum 과 같은 값이어야 한다.
scwin.totalCount = 0;		// 마지막 조회의 전체 건수. 전체 다운로드에서 쓴다.


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 08. 18
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
	// 초기화 함수
	await scwin.init();
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 08. 18
 * @description 초기화. 조회기간 기본값을 잡고 조회영역 동작을 걸어 둔다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 기본 조회기간
 *  - 첫 포커스를 줄 컴포넌트
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
	// 서버 일자를 쓴다. new Date() 는 사용자 PC 시각이라 조회 기준이 흔들린다.
	const today = $c.date.getServerDateTime("yyyyMMdd");

	cal_endDate.setValue(today);
	cal_startDate.setValue($c.date.addMonth(today, -1));

	// 시작일이 종료일보다 뒤면 달력이 스스로 막아 준다. 화면에서 비교문을 쓰지 않는다.
	$c.date.compareFromToDate(cal_startDate, cal_endDate, ["조회 시작일자", "조회 종료일자"], "yyyyMMdd");

	// 조회영역에서 엔터를 치면 조회가 돌게 한다. 조회화면이면 대부분 있어야 하는 동작이다.
	$c.win.setEnterKeyEvent(grp_search, scwin.btn_search_onclick);

	// 검색구분에 맞는 행만 남긴다.
	scwin.setSearchType();

	txt_keyword.focus();
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.rd_schTp_onviewchange
 * @author Inswave
 * @date 2026. 08. 18
 * @description 검색구분 변경. 조회 항목을 갈아끼운다.
 * @param
 * @returns
 * @hidden N
*/
scwin.rd_schTp_onviewchange = function (info) {
	scwin.setSearchType();
};

/**
 * @event
 * @name scwin.btn_period_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 기간 버튼 클릭. 버튼 하나로 여러 기간을 처리한다.
 *
 * 버튼마다 함수를 만들지 않고 userData1 속성에 기간을 적어 한 함수로 받는다.
 * 기간을 추가할 때 마크업만 늘리면 되고 스크립트는 그대로다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_period_onclick = function (e) {
	// 예: userData1="M:3" 이면 3개월 전, "Y:1" 이면 1년 전
	const userData = this.getUserData("userData1") ?? "";
	const [unit, amount] = userData.split(":");

	const endDate = $c.date.getServerDateTime("yyyyMMdd");
	let startDate = endDate;

	// 날짜 가감은 공통함수를 쓴다. Date 객체로 직접 계산하면 월말·윤년에서 어긋난다.
	if (unit === "D") {
		startDate = $c.date.addDate(endDate, -Number(amount));
	} else if (unit === "M") {
		startDate = $c.date.addMonth(endDate, -Number(amount));
	} else if (unit === "Y") {
		startDate = $c.date.addYear(endDate, -Number(amount));
	}

	cal_startDate.setValue(startDate);
	cal_endDate.setValue(endDate);
};

/**
 * @event
 * @name scwin.btn_search_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 조회 버튼 클릭. 첫 페이지부터 다시 읽는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_search_onclick = async function (e) {
	await scwin.searchList(1);
};

/**
 * @event
 * @name scwin.btn_reset_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 초기화 버튼 클릭. 조회조건과 목록을 함께 비운다.
 *
 * 조건만 비우고 목록을 남기면 화면과 조건이 어긋나 보인다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_reset_onclick = async function (e) {
	dma_search.reset();
	dlt_main.removeAll();

	txt_totalCnt.setValue(0);
	pgl_list.setCount(0);

	await scwin.init();
};

/**
 * @event
 * @name scwin.btn_excel_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 현재 페이지 엑셀 다운로드 버튼 클릭.
 *
 * 엑셀 다운로드는 그리드에 올라와 있는 것만 내려받는다.
 * 페이징 화면은 그리드에 현재 페이지분만 있으므로 이 버튼은 지금 보이는 만큼만 받는다.
 * 조건에 맞는 전체가 필요하면 「전체 다운로드」를 쓴다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_excel_onclick = function (e) {
	if (dlt_main.getRowCount() === 0) {
		$c.win.alert("조회된 내용이 없습니다.");
		return;
	}

	scwin.downloadExcel(`ULDINF20000_표준코드조회_${$c.date.getServerDateTime($p, "yyyyMMddHHmmss")}.xlsx`);
};

/**
 * @event
 * @name scwin.btn_excelAll_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 전체 엑셀 다운로드 버튼 클릭.
 *
 * 조회조건에 맞는 전체를 한 번에 받아 그리드에 올린 뒤 내려받고, 원래 페이지로 되돌린다.
 * 엑셀 다운로드가 그리드를 읽기 때문에 전체를 잠깐 올렸다 내리는 것이다.
 *
 * 건수가 많으면 서버와 브라우저 양쪽에 부담이 가므로 상한을 두고 확인을 받는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 전체 다운로드 상한(5000), 파일명
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_excelAll_onclick = async function (e) {
	if (dlt_main.getRowCount() === 0) {
		// "com_search_0011": "조회된 데이터가 없습니다."
		$c.win.alert($c.data.getMessage("com_search_0011"));
		return;
	}

	if (scwin.totalCount > 5000) {
		// "com_search_0070": "한 번에 내려받을 수 있는 건수는 $[0]건입니다.\n조회 조건을 좁혀 주세요."
		$c.win.alert($c.data.getMessage("com_search_0070", [$c.num.formatNumber(5000)]));
		return;
	}

	// 오래 걸릴 수 있는 작업은 시작 전에 건수를 알려주고 확인을 받는다.
	// "com_search_0071": "$[0]건을 모두 내려받습니다. 계속하시겠습니까?"
	if (!await $c.win.confirm($c.data.getMessage("com_search_0071", [$c.num.formatNumber(scwin.totalCount)]))) return;

	const allRows = await scwin.selectAllRows();

	if ($c.util.isEmpty(allRows)) return;

	// 전체를 그리드에 잠시 올린다.
	dlt_main.setJSON(allRows);

	scwin.downloadExcel(`ULDINF20000_표준코드조회_전체목록_${$c.date.getServerDateTime($p, "yyyyMMddHHmmss")}.xlsx`);

	// 원래 보고 있던 페이지로 되돌린다. 이 줄이 없으면 목록이 전체 상태로 남는다.
	await scwin.searchList(scwin.pageIndex);
};

/**
 * @event
 * @name scwin.grd_main_oncellclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 행 클릭. 상세 화면으로 이동하거나 팝업을 여는 자리다.
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_main_oncellclick = function (rowIndex, columnIndex, columnId) {
	const rowData = dlt_main.getRowJSON(rowIndex);

	// 이동할 화면이 정해지면 아래를 살린다.
	// $c.win.moveUrl("/ui/업무/상세화면.xml", { stdCd : rowData.stdCd });
	$c.win.alert("선택한 표준코드 : " + rowData.stdCd);
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 08. 18
 * @description 목록 조회. 페이지 번호를 받아 그 페이지를 읽는다.
 *
 * pageList 컴포넌트가 이 함수를 페이지 번호와 함께 부른다.
 * 그래서 조회 버튼도 페이징도 이 함수 하나만 쓰면 된다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action, target
 *  - 검증 fields
 * @param
 * @returns
 * @hidden N
*/
scwin.searchList = async function (index) {
	if (!await scwin.validateSearch()) return;

	scwin.pageIndex = index ?? 1;

	dma_search.set("page", scwin.pageIndex);
	dma_search.set("size", scwin.pageItemCnt);

	const sbmOptions = {
		id : "sbm_searchList",
		method : "get",
		action : "/api/isin/search/stdCode/select-list-paging",
		ref : "dma_search",
		target : "dlt_main=body.content",
		gridview : "grd_main",
		isProcessMsg : false
	};

	// 통신 오류 시 reject 되므로 catch 로 받는다. 사용자 안내는 공통 오류 핸들러가 한다.
	const result = await $c.sbm.executeDynamic(sbmOptions);

	scwin.setPagingInfo(result);
};

/**
 * @method
 * @name scwin.setPagingInfo
 * @author Inswave
 * @date 2026. 08. 18
 * @description 페이징 컴포넌트를 설정한다.
 *
 * recordCountPerPage 를 넘기지 않으면 공통함수가 기본값 10 을 쓴다.
 * 페이지 수는 전체건수 / recordCountPerPage 로 계산되므로,
 * 한 페이지에 10건이 아닌 화면은 이 값을 반드시 넘겨야 한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - maxRowNum, pageSize
 * @param
 * @returns
 * @hidden N
*/
scwin.setPagingInfo = function (result = {}) {
	const pagingInfo = {
		pageType : "P",							// S/P/A. 기본 P
		rowNumVisble : "grd_main|asc",			// 그리드 행 번호를 전체 순번으로 매긴다
		maxRowNum : scwin.pageItemCnt,			// 그리드에 한 번에 보일 행 수
		pageListId : "pgl_list",					// 페이지 리스트 아이디
		pageFunction : "scwin.searchList",		// 페이지 번호를 눌렀을 때 부를 함수
		currentPage : scwin.pageIndex,
		recordCountPerPage : scwin.pageItemCnt,	// 반드시 넘길 것
		totalCountId : "txt_totalCnt",			// 전체 건수를 출력할 컴포넌트
		pageSize : 10							// 한 번에 보일 페이지 번호 개수
	};

	scwin.totalCount = result.responseJSON?.body?.totalCount ?? 0;

	$c.sbm.setPagingInfo(pagingInfo, "dma_paging", scwin.totalCount);
};

/**
 * @method
 * @name scwin.selectAllRows
 * @author Inswave
 * @date 2026. 08. 18
 * @description 조회조건에 맞는 전체를 한 번에 읽어 배열로 돌려준다.
 *
 * 페이징 조회와 같은 API 를 쓰되 size 만 전체 건수로 올려 부른다.
 * 이때 그리드에 바로 꽂지 않고 배열로 받는다. 그래야 호출한 쪽이 시점을 정할 수 있다.
 *
 * 서버가 size 상한을 두는 경우가 많다. 상한이 있으면 전체 다운로드 상한을 그 값에 맞추거나
 * 페이지를 돌며 이어 붙이는 방식으로 바꾼다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action, 응답 구조
 * @param
 * @returns
 * @hidden N
*/
scwin.selectAllRows = async function () {
	// 조회조건은 그대로 두고 페이지만 전체로 바꿔 부른다.
	dma_search.set("page", 1);
	dma_search.set("size", scwin.totalCount);

	const sbmOptions = {
		id : "sbm_selectAllRows",
		method : "get",
		action : "/api/isin/search/stdCode/select-list-paging",
		ref : "dma_search",
		// 그리드에 꽂지 않는다. 응답만 받아 호출한 쪽에 돌려준다.
		isProcessMsg : false
	};

	const result = await $c.sbm.executeDynamic(sbmOptions);

	return result.responseJSON?.body?.content ?? [];
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setSearchType
 * @author Inswave
 * @date 2026. 08. 18
 * @description 검색구분에 맞는 조회조건 행만 남긴다.
 *
 * 한 화면에서 조건이 갈릴 때는 컴포넌트를 지웠다 만들지 않고
 * 행(tr) 단위로 show/hide 한다. 값도 함께 비워야 이전 조건이 따라가지 않는다.
 *
 * show 는 반드시 빈 문자열을 넘긴다. 인자 없이 부르면 display 가 block 으로 잡혀
 * 행(tr)의 table-row 가 깨지고 표 전체 폭이 무너진다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 구분값과 보여줄 행
 * @param
 * @returns
 * @hidden N
*/
scwin.setSearchType = function () {
	const schTpCd = rd_schTp.getValue();

	trKeyword.hide();
	trPeriod.hide();

	if (schTpCd === "1") {
		trKeyword.show("");
		txt_keyword.focus();
	} else if (schTpCd === "2") {
		trPeriod.show("");
	}
};

/**
 * @method
 * @name scwin.validateSearch
 * @author Inswave
 * @date 2026. 08. 18
 * @description 조회조건을 검증한다.
 *
 * 조회조건 검증은 $c.validate.validateDataCollect 를 쓴다.
 * 조회영역 그룹과 항목 규칙만 넘기면 안내와 포커스 이동까지 처리한다.
 * 화면에서 isEmpty 로 하나씩 확인하고 alert 을 띄우지 않는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - fields 항목
 * @param
 * @returns
 * @hidden N
*/
scwin.validateSearch = async function () {
	const schTpCd = rd_schTp.getValue();

	// 검색구분에 따라 필수 항목이 달라진다.
	if (schTpCd === "1") {
		const options = {
			validateType : "alert",	// alert|mark|all
			checkType : "single",	// single|multi
			focus : true,
			fields : {
				txt_keyword : { required : true, minLength : 2, name : "종목명 및 표준코드" }
			}
		};

		if (!await $c.validate.validateDataCollect(grp_search, options)) return false;

		// 쓰지 않는 조건은 비운다. 남겨 두면 서버가 두 조건을 함께 걸어 결과가 빈다.
		dma_search.set("startDd", "");
		dma_search.set("endDd", "");
	} else if (schTpCd === "2") {
		const options = {
			validateType : "alert",
			checkType : "single",
			focus : true,
			fields : {
				cal_startDate : { required : true, name : "조회 시작일자" },
				cal_endDate : { required : true, name : "조회 종료일자" }
			}
		};

		if (!await $c.validate.validateDataCollect(grp_search, options)) return false;

		dma_search.set("schKeyword", "");
	}

	return true;
};

/**
 * @method
 * @name scwin.downloadExcel
 * @author Inswave
 * @date 2026. 08. 18
 * @description 현재 그리드를 엑셀로 내려받는다.
 *
 * 현재 페이지 다운로드와 전체 다운로드가 파일명만 다르고 나머지는 같아 한 곳에 모았다.
 * 옵션을 바꿀 일이 생기면 여기 한 곳만 고치면 된다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - options
 * @param
 * @returns
 * @hidden N
*/
scwin.downloadExcel = function (fileName) {
	const options = {
		fileName : fileName,
	};

	// 세 번째 인자는 표 위에 얹을 안내행이다. 필요 없으면 빈 배열을 넘긴다.
	$c.data.downloadGridViewExcel(grd_main, options, []);
};

/**
 * @method
 * @name scwin.dateFormatter
 * @author Inswave
 * @date 2026. 08. 18
 * @description 그리드 일자 컬럼 표시 형식. yyyyMMdd 를 yyyy-MM-dd 로 보여준다.
 *
 * 저장값은 그대로 두고 보이는 값만 바꾼다. dataList 값을 직접 고치면
 * 저장·재조회 때 형식이 섞여 서버가 받지 못한다.
 *
 * formatDate 의 두 번째 인자는 포맷 문자열이 아니라 구분자 한 글자다.
 * "yyyy-MM-dd" 처럼 넘기면 그 문자열이 그대로 사이에 끼어 들어간다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 구분자
 * @param
 * @returns
 * @hidden N
*/
scwin.dateFormatter = function (data) {
	if ($c.util.isEmpty(data)) return "";

	return $c.date.formatDate(data, "-");
};
